sys_security_acl.script:
answer = false;

if (gs.hasRole('x_1921506_incide_0.x_iae_admin') ||
    gs.hasRole('x_1921506_incide_0.x_iae_team_lead')) {

    answer = true;

} else if (gs.hasRole('x_1921506_incide_0.x_iae_agent')) {

    // Allow the agent to read their own record
    if (current.getValue('agent') == gs.getUserID()) {
        answer = true;

    }
    if (gs.hasRole('x_1921506_incide_0.x_iae_agent')) {


        var agentGR = new GlideRecord('x_1921506_incide_0_agent_skill');

        var condition = agentGR.addQuery('agent', gs.getUserID());
        condition.addOrCondition('agent', current.getValue('agent'));

        agentGR.query();

        var cat = [];
        var cat1 = [];

        while (agentGR.next()) {

            if (agentGR.getValue('agent') == gs.getUserID()) {
                cat.push(agentGR.getValue('category'));
            }

            if (agentGR.getValue('agent') == current.getValue('agent')) {
                cat1.push(agentGR.getValue('category'));
            }
        }
        var len = cat.length + cat1.length;
        for (var i = 0; i < len; i++) {
            if (cat[i] && cat1[i] && cat[i] == cat1[i]) {
                answer = true;
            }
        }
        // var agentGR1 = new GlideRecord('x_1921506_incide_0_agent_skill');

        // agentGR1.addQuery('agent', current.getValue('agent'));
        // agentGR1.setLimit(1);
        // agentGR1.query();

        // if (agentGR1.next()) {

        //     var cat1 = agentGR1.getValue('category');


        // }
        // if (cat && cat1 && cat == cat1) {
        //     answer = true;
        // }


    }
}
